'use strict';

// MODULES //

var hasOwnProp = require( '@stdlib/assert/has-own-property' );


// VARIABLES //

var CDN_PREFIX = 'https://cdn.jsdelivr.net/gh/stdlib-js/';
var CDN_SUFFIX = '@esm/index.mjs';
var RESOLVER_VERSION = 2;


// FUNCTIONS //

/**
* Tests whether a stdlib specifier has a canonical, non-URL-like form.
*
* @private
* @param {string} specifier - module specifier
* @returns {boolean} boolean
*/
function isStdlibSpecifier( specifier ) {
	var parts;
	var i;

	if (
		typeof specifier !== 'string' ||
		specifier.slice( 0, 8 ) !== '@stdlib/' ||
		/[?#%\\]/.test( specifier )
	) {
		return false;
	}
	parts = specifier.slice( 8 ).split( '/' );
	for ( i = 0; i < parts.length; i++ ) {
		if ( !/^[a-z0-9][a-z0-9_-]*$/.test( parts[ i ] ) || parts[ i ] === '.' || parts[ i ] === '..' ) {
			return false;
		}
	}
	return parts.length > 0;
}

/**
* Copies a resolution record.
*
* @private
* @param {Object} record - convention or overlay record
* @param {string} source - resolver source
* @returns {Object} copied record
*/
function copy( record, source ) {
	var out = {
		'export': record.export,
		'mutable': record.mutable,
		'runtimes': record.runtimes.slice(),
		'url': record.url,
		'resolverSource': source,
		'resolverVersion': RESOLVER_VERSION
	};

	if ( record.repository ) {
		out.repository = record.repository;
	}
	return out;
}

/**
* Resolves a canonical stdlib package using the standalone ESM convention.
*
* @private
* @param {string} specifier - canonical stdlib specifier
* @returns {Object} resolution record
*/
function stdlib( specifier ) {
	var repository = specifier.slice( 8 ).replace( /\//g, '-' );

	return {
		'export': 'default',
		'mutable': true,
		'repository': repository,
		'runtimes': [ 'worker', 'iframe' ],
		'url': CDN_PREFIX+repository+CDN_SUFFIX
	};
}


// MAIN //

/**
* Resolves an authored module specifier for a JupyterLite runtime.
*
* @param {string} specifier - authored module specifier
* @param {Object} options - converter options
* @param {string} runtime - target runtime
* @returns {Object} resolution result
*/
function resolve( specifier, options, runtime ) {
	var record;
	var source;

	if ( hasOwnProp( options.moduleMap, specifier ) ) {
		record = options.moduleMap[ specifier ];
		source = 'module-map';
	} else {
		if ( !isStdlibSpecifier( specifier ) ) {
			return {
				'ok': false,
				'code': 'unsupported-module-specifier',
				'message': 'Module specifier is not present in the explicit module map.'
			};
		}
		record = stdlib( specifier );
		source = 'stdlib-esm-convention';
	}
	if ( record.runtimes.indexOf( runtime ) === -1 ) {
		return {
			'ok': false,
			'code': 'runtime-incompatible-module',
			'message': 'Resolved module does not support the selected JupyterLite runtime.'
		};
	}
	return {
		'ok': true,
		'record': copy( record, source )
	};
}


// EXPORTS //

resolve.isStdlibSpecifier = isStdlibSpecifier;
module.exports = resolve;
